h1 {
  text-align: center;
  color: #8B2E2E;
}
.panel {
  display: flex;
  gap: 16px;
  margin-bottom: 20px;
}
.section {
  flex: 1;
  background: #FFFAF2;
  border: 1px solid #D4C5A9;
  border-radius: 8px;
  padding: 16px;
}
.section.result {
  background: #FFF8F0;
  border-color: #C9A96E;
}
.section h2 {
  color: #8B2E2E;
  font-size: 14px;
  margin: 0 0 8px 0;
}
.section p {
  color: #3D2B1F;
  font-size: 15px;
  margin: 0;
  min-height: 24px;
}
.controls {
  display: flex;
  gap: 8px;
  justify-content: center;
}
#filterInput {
  padding: 10px 14px;
  border: 1px solid #D4C5A9;
  border-radius: 6px;
  font-size: 14px;
  font-family: inherit;
  width: 200px;
}
#resetBtn {
  padding: 10px 20px;
  background: #8B2E2E;
  color: #fff;
  border: none;
  border-radius: 6px;
  font-size: 14px;
  cursor: pointer;
}
#resetBtn:hover {
  background: #C94545;
}

starter.js:
let composers = ["Bach", "Mozart", "Beethoven", "Chopin", "Debussy", "Vivaldi"];
// 显示原始列表
let originalEl = document.querySelector("#original");
let outputEl = document.querySelector("#output");
originalEl.textContent = composers.join(" · ");
// 筛选+转换函数
function updateList(letter) {
  let result = composers
    .filter(function(name) {
      return name.toLowerCase().includes(letter.toLowerCase());
    })
    .map(function(name) {
      return name.toUpperCase();
    });
  outputEl.textContent = result.length > 0 ? result.join(" | ") : "（无匹配）";
}
// 初始显示全部
updateList("");
// 输入筛选
document.querySelector("#filterInput").addEventListener("input", function() {
  updateList(this.value);
});
// 重置
document.querySelector("#resetBtn").addEventListener("click", function() {
  document.querySelector("#filterInput").value = "";
  updateList("");
});
